chartjs.data:
model -> {
	since = now().toSystemCalendar().withDayAdded(-30).toDate().roundDay();
	billable = e -> ifElse(isEmpty($e.get(`tl.ai.execution:AgentExecution#inputTokens`)), 0, $e.get(`tl.ai.execution:AgentExecution#inputTokens`))
		+ ifElse(isEmpty($e.get(`tl.ai.execution:AgentExecution#outputTokens`)), 0, $e.get(`tl.ai.execution:AgentExecution#outputTokens`));
	byAgent = all(`tl.ai.execution:AgentExecution`)
		.filter(e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`) >= $since)
		.groupBy(e -> $e.get(`tl.ai.execution:AgentExecution#agentName`));
	ranked = $byAgent.keySet().toList().sort(desc(comparator(a -> $byAgent[$a].map(e -> $billable($e)).sum())));
	names = ifElse($ranked.size() > 10, $ranked.subList(0, 10), $ranked);
	{
		'type': 'bar',
		'data': {
			'labels': $names,
			'datasets': list({
				'label': #('Billable tokens'@en, 'Abrechenbare Token'@de).localize(),
				'data': $names.map(a -> $byAgent[$a].map(e -> $billable($e)).sum()),
				'backgroundColor': '#2968c8',
				'maxBarThickness': 26
			})
		},
		'options': {
			'indexAxis': 'y',
			'maintainAspectRatio': false,
			'plugins': { 'legend': { 'display': false } },
			'scales': { 'x': { 'beginAtZero': true } }
		}
	};
}
